  'Detections and scanning': ['检测与扫描', '検出とスキャン', 'Detecciones y análisis', 'Обнаружения и сканирование', 'Rilevamenti e scansione'],
  'Persistence': ['持久化', '永続化', 'Persistencia', 'Закрепление в системе', 'Persistenza'],
